import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  LineChart,
  ReferenceLine,
  ResponsiveContainer,
  XAxis,
  YAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ERA_AVERAGES,
  HEADLINE,
  SOURCE_NOTE,
  filterFlows,
  flowVsCompactSeries,
  fmtMaf,
  fmtPct,
  gapByEra,
  lowerBasinBars,
  meanNatural,
  paperClaimBars,
  rolling10yrMeans,
  useVsEntitlementBars,
  type FlowWindow,
} from "@/data/colorado-river-compact-vs-actual-flows-2026-data";

// viz-types: flow vs compact composed, gap bars, paper-claim stack, lower-basin bars, use-vs-entitlement grouped, rolling-10 line | layout: default

type ViewId = "flows" | "gaps" | "claims" | "use";

const RIVER = "#0369a1";
const COMPACT = "#b45309";
const CLAIM = "#7c3aed";
const GAP = "#be123c";
const TEAL = "#0f766e";
const SLATE = "#64748b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

